def _read_body(self, code, headers, delegate):
    # Normalize header names for case insensitivity
    headers = {k.lower(): v for k, v in headers.items()}

    if "content-length" in headers:
        if "transfer-encoding" in headers:
            # Response cannot contain both Content-Length and Transfer-Encoding headers.
            raise httputil.HTTPInputError(
                "Response with both Transfer-Encoding and Content-Length")

        if "," in headers["content-length"]:
            # Proxies sometimes cause Content-Length headers to get duplicated.
            pieces = re.split(r',\s*', headers["content-length"])
            if any(i != pieces[0] for i in pieces):
                raise httputil.HTTPInputError(
                    "Multiple unequal Content-Lengths: %r" %
                    headers["content-length"])
            headers["content-length"] = pieces[0]

        try:
            content_length = int(headers["content-length"])
        except ValueError:
            # Handles non-integer Content-Length value.
            raise httputil.HTTPInputError(
                "Only integer Content-Length is allowed: %s" % headers["content-length"])

        if content_length > self._max_body_size:
            raise httputil.HTTPInputError("Content-Length too long")
    else:
        content_length = None

    if code == 204:
        # Check for the 204 No Content response
        if ("transfer-encoding" in headers or
                content_length not in (None, 0)):
            raise httputil.HTTPInputError(
                "Response with code %d should not have body" % code)
        content_length = 0

    if content_length is not None:
        return self._read_fixed_body(content_length, delegate)
    if headers.get("transfer-encoding") == "chunked":
        return self._read_chunked_body(delegate)
    if self.is_client:
        return self._read_body_until_close(delegate)
    return None
